import json
H,W=17,30
g=[[0]*W for _ in range(H)]
# Same motif is transferred to every panel cell; reconstruct each of four independently from the test.
patterns={
3:[(0,[0,1,2,3,4]),(1,[2]),(2,[1,2,3]),(3,[0,1,2,3,4]),(4,[2])],
8:[(0,[0,1,2,3,4]),(1,[2]),(2,[1,2,3]),(3,[0,1,2,3,4]),(4,[2])],
4:[(0,[0,1,2,3,4]),(1,[2]),(2,[1,2,3]),(3,[0,1,2,3,4]),(4,[2])],
1:[(0,[0,1,2,3,4]),(1,[2]),(2,[1,2,3]),(3,[0,1,2,3,4]),(4,[2])],
}
for color,left in [(3,2),(1,9),(4,14),(8,21)]:
 for dr,cols in patterns[color]:
  for dc in cols:g[2+dr][left+dc]=color
assert len(g)==17 and set(map(len,g))=={30}
print('valid',len(g),set(map(len,g)))
print(json.dumps(g,separators=(',',':')))

