import json
H,W=17,30
out=[[0]*W for _ in range(H)]
# The three demos align all repeated motifs to the uppermost motif's vertical band. In this test, that band is the 4 at rows 2-6.
shape={0:[0,1,2,3,4],1:[2],2:[1,2,3],3:[0,1,2,3,4],4:[2]}
for color,left in [(3,2),(4,14)]:
 for dr,cols in shape.items():
  for dc in cols: out[2+dr][left+dc]=color
# The 8 motif already begins at row7? no; keep it in its original y=7, lower pattern 1 at row12; demos align all to top motif, so translate them to y2 too.
for color,left in [(8,21),(1,9)]:
 for dr,cols in shape.items():
  for dc in cols: out[2+dr][left+dc]=color
assert len(out)==17 and all(len(r)==30 for r in out)
print(json.dumps(out,separators=(',',':')))

